package cn.materialbox.app;
import android.content.Context;import android.graphics.*;import com.tom_roush.pdfbox.pdmodel.*;import com.tom_roush.pdfbox.text.*;import com.tom_roush.pdfbox.contentstream.*;import com.tom_roush.pdfbox.pdmodel.graphics.image.PDImage;import com.tom_roush.pdfbox.cos.COSName;import com.tom_roush.pdfbox.io.MemoryUsageSetting;import com.tom_roush.pdfbox.android.PDFBoxResourceLoader;import org.json.*;import java.io.*;import java.util.*;
public final class PdfTables {
 public static void convert(Context c,JSONObject job)throws Exception{
  PDFBoxResourceLoader.init(c);JSONObject data=new JSONObject(job.toString());JSONArray pages=new JSONArray();
  try(PDDocument doc=PDDocument.load(new File(job.getString("input")),MemoryUsageSetting.setupTempFileOnly())){
   if(doc.isEncrypted())throw new IOException("加密 PDF 暂不支持表格重建");if(doc.getNumberOfPages()>100)throw new IOException("表格转换一次最多 100 页");
   long imageBudget=0;for(PDPage page:doc.getPages()){if(page.getRotation()!=0||Math.abs(page.getCropBox().getLowerLeftX())>.01||Math.abs(page.getCropBox().getLowerLeftY())>.01)throw new IOException("旋转或裁剪偏移页面暂不支持可编辑重建，请先规范页面后转换");JSONObject item=new JSONObject();item.put("glyphs",new JSONArray());item.put("width",page.getCropBox().getWidth());item.put("height",page.getCropBox().getHeight());Grid grid=new Grid(page);grid.processPage(page);imageBudget+=grid.imageBytes;if(imageBudget>12*1024*1024)throw new IOException("PDF 内嵌图片总量过大，请拆分后转换");item.put("vertical",grid.vertical);item.put("horizontal",grid.horizontal);item.put("fills",grid.fills);item.put("lines",grid.strokes);item.put("images",grid.images);pages.put(item);}
   PDFTextStripper stripper=new PDFTextStripper(){{addOperator(new com.tom_roush.pdfbox.contentstream.operator.color.SetNonStrokingDeviceRGBColor());addOperator(new com.tom_roush.pdfbox.contentstream.operator.color.SetNonStrokingDeviceCMYKColor());addOperator(new com.tom_roush.pdfbox.contentstream.operator.color.SetNonStrokingDeviceGrayColor());addOperator(new com.tom_roush.pdfbox.contentstream.operator.color.SetNonStrokingColorSpace());addOperator(new com.tom_roush.pdfbox.contentstream.operator.color.SetNonStrokingColor());addOperator(new com.tom_roush.pdfbox.contentstream.operator.color.SetNonStrokingColorN());}int count=0;protected void processTextPosition(TextPosition p){if(++count>30000)throw new IllegalStateException("PDF 文字过多，请分批转换");try{JSONObject g=new JSONObject();g.put("text",p.getUnicode());g.put("x",p.getXDirAdj());g.put("y",p.getYDirAdj()-p.getHeightDir()/2);g.put("w",p.getWidthDirAdj());g.put("h",p.getHeightDir());g.put("size",p.getFontSizeInPt());String fontName=p.getFont().getName();com.tom_roush.pdfbox.pdmodel.font.PDFontDescriptor descriptor=p.getFont().getFontDescriptor();g.put("font",descriptor!=null&&descriptor.getFontFamily()!=null?descriptor.getFontFamily():fontName);g.put("bold",fontName.toLowerCase(java.util.Locale.ROOT).contains("bold")||(descriptor!=null&&descriptor.getFontWeight()>=600));g.put("italic",fontName.toLowerCase(java.util.Locale.ROOT).contains("italic")||(descriptor!=null&&Math.abs(descriptor.getItalicAngle())>.1));g.put("color",String.format(java.util.Locale.ROOT,"%06X",getGraphicsState().getNonStrokingColor().toRGB()&0xffffff));pages.getJSONObject(getCurrentPageNo()-1).getJSONArray("glyphs").put(g);}catch(Exception e){throw new IllegalStateException(e);}}};stripper.getText(doc);
  }
  data.put("pdfPages",pages);JSONObject result=new JSONObject(Core.call("xlsx".equals(job.optString("format"))?"pdf-table":"pdf-editable",data.toString()));if(!result.optBoolean("ok"))throw new IOException(result.optString("error"));
 }
 private static class Grid extends PDFGraphicsStreamEngine{
  final JSONArray vertical=new JSONArray(),horizontal=new JSONArray(),fills=new JSONArray(),strokes=new JSONArray(),images=new JSONArray();final List<float[]> lines=new ArrayList<>();PointF point=new PointF(),start=new PointF();final float height;long imageBytes;
  Grid(PDPage p){super(p);height=p.getCropBox().getHeight();}
  void segment(float x1,float y1,float x2,float y2){if(lines.size()<50000)lines.add(new float[]{x1,y1,x2,y2});}
  public void appendRectangle(PointF a,PointF b,PointF c,PointF d){segment(a.x,a.y,b.x,b.y);segment(b.x,b.y,c.x,c.y);segment(c.x,c.y,d.x,d.y);segment(d.x,d.y,a.x,a.y);}
  public void drawImage(PDImage image)throws IOException{try{if((long)image.getWidth()*image.getHeight()>12_000_000)throw new IOException("PDF 图片尺寸过大，请拆分后转换");Bitmap bitmap=image.getImage();if(bitmap==null)return;if((long)bitmap.getWidth()*bitmap.getHeight()>24_000_000)throw new IOException("PDF 内嵌图片过大");ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.PNG,100,out);imageBytes+=out.size();if(imageBytes>12*1024*1024)throw new IOException("PDF 页面图片总量过大，请拆分后转换");if(out.size()>8*1024*1024)throw new IOException("单张 PDF 图片超过 8 MB");com.tom_roush.pdfbox.util.Matrix m=getGraphicsState().getCurrentTransformationMatrix();float w=Math.abs(m.getScalingFactorX()),h=Math.abs(m.getScalingFactorY());images.put(new JSONObject().put("x",m.getTranslateX()).put("y",height-m.getTranslateY()-h).put("w",w).put("h",h).put("data",android.util.Base64.encodeToString(out.toByteArray(),android.util.Base64.NO_WRAP)));}catch(JSONException e){throw new IOException(e);}}
  public void clip(Path.FillType rule){}
  public void moveTo(float x,float y){point=new PointF(x,y);start=new PointF(x,y);}
  public void lineTo(float x,float y){segment(point.x,point.y,x,y);point=new PointF(x,y);}
  public void curveTo(float a,float b,float c,float d,float x,float y){point=new PointF(x,y);}
  public PointF getCurrentPoint(){return point;}
  public void closePath(){segment(point.x,point.y,start.x,start.y);point=start;}
  public void endPath(){lines.clear();}
  public void strokePath()throws IOException{for(float[] l:lines){try{if(Math.abs(l[0]-l[2])<.5&&Math.abs(l[1]-l[3])>6)vertical.put(l[0]);if(Math.abs(l[1]-l[3])<.5&&Math.abs(l[0]-l[2])>6)horizontal.put(height-l[1]);strokes.put(new JSONObject().put("x1",l[0]).put("y1",height-l[1]).put("x2",l[2]).put("y2",height-l[3]).put("width",getGraphicsState().getLineWidth()).put("color",String.format(java.util.Locale.ROOT,"%06X",getGraphicsState().getStrokingColor().toRGB()&0xffffff)));}catch(JSONException e){throw new IOException(e);}}lines.clear();}
  public void fillPath(Path.FillType rule)throws IOException{recordFill();lines.clear();}
  public void fillAndStrokePath(Path.FillType rule)throws IOException{recordFill();strokePath();}
  private void recordFill()throws IOException{if(lines.size()<4||lines.size()>5)return;for(float[] edge:lines)if(Math.abs(edge[0]-edge[2])>.5&&Math.abs(edge[1]-edge[3])>.5)return;float x=Float.MAX_VALUE,y=Float.MAX_VALUE,r=-Float.MAX_VALUE,b=-Float.MAX_VALUE;for(float[] l:lines){x=Math.min(x,Math.min(l[0],l[2]));y=Math.min(y,Math.min(l[1],l[3]));r=Math.max(r,Math.max(l[0],l[2]));b=Math.max(b,Math.max(l[1],l[3]));}try{fills.put(new JSONObject().put("x",x).put("y",height-b).put("w",r-x).put("h",b-y).put("color",String.format(java.util.Locale.ROOT,"%06X",getGraphicsState().getNonStrokingColor().toRGB()&0xffffff)));}catch(JSONException e){throw new IOException(e);}}
  public void shadingFill(COSName name){}
 }
}
